{
  "themes": [
    {
      "cluster": 0,
      "name": "Baggage Handling Issues",
      "description": "Customers report lost, damaged, or improperly routed luggage and ask about checking rules."
    },
    {
      "cluster": 1,
      "name": "Direct Message Follow‑Up",
      "description": "Customers mention sending or awaiting a DM and request a response or action."
    },
    {
      "cluster": 2,
      "name": "In‑Flight Entertainment Power Problems",
      "description": "Customers complain that seat screens, TVs, or power outlets are not working during flights."
    },
    {
      "cluster": 3,
      "name": "Paid Wi‑Fi Performance Complaints",
      "description": "Customers who paid for Wi‑Fi say the connection is poor or non‑functional and seek refunds."
    },
    {
      "cluster": 4,
      "name": "Free Wi‑Fi and Messaging Praise",
      "description": "Customers express satisfaction with complimentary Wi‑Fi or free messaging services on board."
    },
    {
      "cluster": 5,
      "name": "TSA Pre‑Check / KTN Missing",
      "description": "Customers notice their TSA Pre‑Check or Known Traveler Number isn’t applied to their reservation."
    },
    {
      "cluster": 6,
      "name": "Medallion Status Upgrade Feedback",
      "description": "Customers discuss receiving or missing upgrades tied to their loyalty tier (Silver, Gold, Platinum, Diamond)."
    },
    {
      "cluster": 7,
      "name": "Boarding Zone & Priority Boarding Confusion",
      "description": "Customers describe chaos or questions around boarding zones, priority boarding, and Sky Club access."
    },
    {
      "cluster": 8,
      "name": "Seat Comfort and Upgrade Experiences",
      "description": "Customers share experiences of seat assignments, upgrades, or discomfort in assigned seats."
    },
    {
      "cluster": 9,
      "name": "Complimentary Upgrade Requests",
      "description": "Customers thank the airline for complimentary upgrades or inquire about managing them."
    },
    {
      "cluster": 10,
      "name": "JFK Arrival Delays and Ground Issues",
      "description": "Customers report delays, emergency landings, or ground‑service problems at JFK."
    },
    {
      "cluster": 11,
      "name": "Early Morning Flight Sentiment",
      "description": "Customers post positive or neutral remarks about early‑morning flights and sunrise experiences."
    }
  ]
}
